import{_ as r,a8 as e,o as l,c as i,ah as s,K as o}from"./chunks/framework.D31WLDJp.js";import"./chunks/theme.CP9whvzN.js";const f=JSON.parse('{"title":"小黑日报 → Obsidian 日记工作流","description":"","frontmatter":{"type":"workflow","scope":"global","created":"2026-09-12T00:00:00.000Z","updated":"2026-09-12T00:00:00.000Z","tags":["工作流","小黑日报","Obsidian","日记"]},"headers":[],"relativePath":"vault/Memory/Workflows/小黑日报-Obsidian日记工作流.md","filePath":"vault/Memory/Workflows/小黑日报-Obsidian日记工作流.md","lastUpdated":1789374053000}'),c={name:"vault/Memory/Workflows/小黑日报-Obsidian日记工作流.md"};function n(h,t,b,_,g,m){const d=e("NolebaseGitContributors"),a=e("NolebaseGitChangelog");return l(),i("div",null,[t[0]||(t[0]=s('<h1 id="小黑日报-→-obsidian-日记工作流" tabindex="-1">小黑日报 → Obsidian 日记工作流 <a class="header-anchor" href="#小黑日报-→-obsidian-日记工作流" aria-label="Permalink to “小黑日报 → Obsidian 日记工作流”">​</a></h1><blockquote><p>每天一次：小黑日报助手按模板生成当日记录 → 整块粘进当天日记 → 其余段落本人自由补写。 模板配置源：<code>[[小黑报告模板]]</code>（<code>vault/Templates/小黑报告模板.md</code>）</p></blockquote><h2 id="关键文件" tabindex="-1">关键文件 <a class="header-anchor" href="#关键文件" aria-label="Permalink to “关键文件”">​</a></h2><table tabindex="0"><thead><tr><th>用途</th><th>路径</th></tr></thead><tbody><tr><td>小黑报告模板（配置源，含三块填法）</td><td><code>vault/Templates/小黑报告模板.md</code></td></tr><tr><td>Obsidian 日记模板</td><td><code>vault/Templates/DailyNote.md</code>（内含空的 <code>## 📋 今日记录（小黑生成）</code>）</td></tr><tr><td>日记落点</td><td><code>vault/DailyNotes/&lt;年&gt;/YYYY_MM_DD.md</code></td></tr></tbody></table><h2 id="三步操作" tabindex="-1">三步操作 <a class="header-anchor" href="#三步操作" aria-label="Permalink to “三步操作”">​</a></h2><ol><li>新建当天日记（日记模板自动填 <code>created</code> 与 MOC 链接）</li><li>小黑按模板生成 → 复制 5 个 <code>###</code> 块</li><li>粘到日记 <code>## 📋 今日记录（小黑生成）</code> 下方；无内容的段落直接删除，不保留占位</li></ol><h2 id="小黑「创建模板」三块分工" tabindex="-1">小黑「创建模板」三块分工 <a class="header-anchor" href="#小黑「创建模板」三块分工" aria-label="Permalink to “小黑「创建模板」三块分工”">​</a></h2><ul><li><strong>模板名称</strong>：<code>今日记录</code></li><li><strong>模板正文</strong>：只放<strong>结构骨架</strong>（5 个 <code>###</code> 标题 + <code>[占位符]</code>），<strong>不能</strong>填填好的示例——AI 会照抄示例文字</li><li><strong>自定义指令</strong>：只放输出约束（结构归正文、约束归指令）</li></ul><h2 id="归档易错点" tabindex="-1">归档易错点 <a class="header-anchor" href="#归档易错点" aria-label="Permalink to “归档易错点”">​</a></h2><ul><li>⚠️ <strong>按报告本身标注的日期归档，不用系统日期</strong>。曾把 9-10 的报告误存为 <code>2026_09_11.md</code>（当时系统日期已是 9-11），需改名 + 改 <code>created</code> 两处。</li><li>日记里无内容的模板段落（今日焦点/学习进度/实战/想法/产出笔记/未解决/个人）<strong>一律删除</strong>，不代写、不留空占位。</li></ul><h2 id="分块与分类要点-v4-定稿" tabindex="-1">分块与分类要点（v4 定稿） <a class="header-anchor" href="#分块与分类要点-v4-定稿" aria-label="Permalink to “分块与分类要点（v4 定稿）”">​</a></h2><ul><li>5 个块固定顺序：<code>📌 今日做了什么</code> / <code>💡 学到的·搞懂的</code> / <code>🔧 操作备忘</code> / <code>🧩 卡住·待解决</code> / <code>🎯 明天打算</code>；每个必现，空写「暂无」</li><li>输出用 <code>###</code> 不用 <code>##</code>（要嵌进日记的 <code>##</code> 小节）、不输出 frontmatter</li><li><strong>6 组互斥</strong>：求职/面试、写作/输出、阅读/调研、学习/课程、个人项目（按具体项目再分子组）、生活事务；禁止把什么都塞进「个人项目」</li><li>主题名<strong>加粗单独一行</strong>、其下列事项，不要每条重复「主题：」前缀；一组 &gt;6 条拆或合并</li><li>同一件事的多个步骤合并成一条；每条尽量可量化</li><li><strong>学到的 vs 操作备忘</strong>：下次能照着执行一遍的（含参数值/命令/路径/配置项）→ 操作备忘；改变理解、解释「为什么」→ 学到的；同一件事不重复出现在两处</li><li><strong>卡住</strong>写阻塞原因与当前状态，<strong>明天打算</strong>写下一步动作，两者措辞不得整句重复</li></ul><h2 id="迭代史-踩过的坑" tabindex="-1">迭代史（踩过的坑） <a class="header-anchor" href="#迭代史-踩过的坑" aria-label="Permalink to “迭代史（踩过的坑）”">​</a></h2><table tabindex="0"><thead><tr><th>版本</th><th>问题</th><th>修正</th></tr></thead><tbody><tr><td>v1</td><td>结构对了，但「个人项目：」前缀连写 8 次、主题被打散</td><td>改为真聚类：主题名加粗单独一行</td></tr><tr><td>v2</td><td>「个人项目」成兜底桶，吞掉求职/写作两组（膨胀到 11 条）</td><td>分类词表加互斥约束 + 个人项目按具体项目分子组 + 组 &gt;6 条拆分</td></tr><tr><td>v3</td><td>操作类知识无处安放，仍塞回「学到的」</td><td>新增第 5 块 <code>🔧 操作备忘</code></td></tr><tr><td>v4</td><td>同源知识在「学到的」与「操作备忘」重复；跨块整句重复</td><td>加可执行判定规则 + 卡住/明天打算措辞区分</td></tr></tbody></table><h2 id="隐私" tabindex="-1">隐私 <a class="header-anchor" href="#隐私" aria-label="Permalink to “隐私”">​</a></h2><ul><li><code>**/Templates/**</code> 与 <code>**/DailyNotes/**</code> 均在 VitePress <code>srcExclude</code>（config.ts 第 58/126 行），<strong>模板与日记都不会发布到公开站点</strong></li><li>模板文件已脱敏（无真实项目名/公司名/仓库名/作品名），可对外分享；日记内含公司名、背调结论等，但不上站</li></ul>',16)),o(d),o(a)])}const v=r(c,[["render",n]]);export{f as __pageData,v as default};
